    #[test]
    fn settings_are_sorted() {
        assert!(PULL_ZONE_SETTINGS.windows(2).all(|w| w[0].0 < w[1].0));
    }

    #[test]
    fn lookup_is_case_insensitive() {
        assert_eq!(lookup(EDGE_RULE_ACTION_TYPES, "setresponseheader"), Some(5));
        assert_eq!(lookup(EDGE_RULE_ACTION_TYPES, "nope"), None);
        assert_eq!(
            name_of(EDGE_RULE_ACTION_TYPES, 5),
            Some("SetResponseHeader")
        );
    }
